  "query": "begin;
set local role authenticated;
set local request.jwt.claim.sub = '11111111-1111-1111-1111-111111111111';
insert into public.tasks (title) values ('rls update verification') returning id, user_id, is_done;
update public.tasks set is_done = true where title = 'rls update verification' returning id, user_id, is_done;
reset role;
delete from public.tasks where title = 'rls update verification';
commit;"
}

